import unittest


def strange_sort_list(lst):
    res, switch = [], True
    while lst:
        res.append(min(lst) if switch else max(lst))
        lst.remove(res[-1])
        switch = not switch
    return res


class TestStrangeSortList(unittest.TestCase):

    def test_empty_list(self):
        self.assertEqual(strange_sort_list([]), [])

    def test_single_element(self):
        self.assertEqual(strange_sort_list([1]), [1])

    def test_two_elements(self):
        self.assertEqual(strange_sort_list([1, 2]), [1, 2])

    def test_typical_case(self):
        self.assertEqual(strange_sort_list([1, 2, 3, 4]), [1, 4, 2, 3])

    def test_another_typical_case(self):
        self.assertEqual(strange_sort_list([5, 5, 5, 5]), [5, 5, 5, 5])

    def test_unsorted_input(self):
        self.assertEqual(strange_sort_list([3, 1, 4, 2, 5]), [1, 5, 2, 4, 3])

    def test_negative_numbers(self):
        self.assertEqual(strange_sort_list([-1, -5, 0, 3]), [-5, 3, -1, 0])

    def test_duplicates(self):
        self.assertEqual(strange_sort_list([2, 2, 1, 3]), [1, 3, 2, 2])

    def test_already_min_max_sorted(self):
        self.assertEqual(strange_sort_list([10, 1]), [1, 10])

    def test_mixed_values(self):
        self.assertEqual(strange_sort_list([7, 0, -3, 9, 4]), [-3, 9, 0, 7, 4])


if __name__ == "__main__":
    unittest.main()
